import Foundation
import CryptoKit

// Message Queue Consumer with Encrypted Storage
class SecureMessageQueue {
    private var storageKey: SymmetricKey
    private var messageBuffer: UnsafeMutableRawBufferPointer
    private let bufferSize: Int = 4096
    private var writeOffset: Int = 0
    private var functionTable: [UInt64] = []

    struct MessageHeader {
        var payloadLength: UInt32
        var handlerIndex: UInt32
        var nonce: [UInt8]
        var tag: [UInt8]
    }

    typealias MessageHandler = @convention(c) (UnsafeRawPointer, Int) -> Void

    private var handlers: [MessageHandler] = []

    init(keyData: Data) {
        self.storageKey = SymmetricKey(data: keyData)
        self.messageBuffer = UnsafeMutableRawBufferPointer.allocate(
            byteCount: bufferSize,
            alignment: MemoryLayout<UInt64>.alignment
        )
        self.messageBuffer.initializeMemory(as: UInt8.self, repeating: 0)
        registerDefaultHandlers()
    }

    private func registerDefaultHandlers() {
        handlers.append(logHandler)
        handlers.append(storeHandler)
        handlers.append(forwardHandler)
    }

    func consumeMessage(encryptedPayload: Data, header: MessageHeader) throws {
        let nonce = try AES.GCM.Nonce(data: Data(header.nonce))
        let sealedBox = try AES.GCM.SealedBox(
            nonce: nonce,
            ciphertext: encryptedPayload,
            tag: Data(header.tag)
        )
        let decrypted = try AES.GCM.open(sealedBox, using: storageKey)

        try processDecryptedMessage(decrypted, header: header)
    }

    private func processDecryptedMessage(_ data: Data, header: MessageHeader) throws {
        let payloadLength = Int(header.payloadLength)

        // Validate handler index is within registered handlers
        guard header.handlerIndex < UInt32(handlers.count) else {
            throw QueueError.invalidHandler
        }

        // Copy decrypted data into the execution buffer
        // Use actual decrypted data length, not the header-specified length
        let copyLength = min(payloadLength, data.count)

        // Ensure the copy can never exceed the destination buffer capacity,
        // even after a wrap-around reset. This protects the destination buffer
        // independently of the source-read bounding.
        guard copyLength <= bufferSize else {
            throw QueueError.bufferOverflow
        }

        guard writeOffset + copyLength <= bufferSize else {
            writeOffset = 0 // wrap around
            return try processDecryptedMessage(data, header: header)
        }

        data.withUnsafeBytes { srcPtr in
            let dest = messageBuffer.baseAddress!.advanced(by: writeOffset)
            // Safely use the bounded copyLength for the memcpy operation
            memcpy(dest, srcPtr.baseAddress!, copyLength)
        }

        writeOffset += copyLength

        // Dispatch to handler
        let handlerPtr = messageBuffer.baseAddress!.advanced(by: writeOffset - copyLength)
        handlers[Int(header.handlerIndex)](handlerPtr, copyLength)
    }

    func storeToEncryptedDisk(at path: String) throws {
        let sanitizedPath = URL(fileURLWithPath: path).standardized.path
        guard sanitizedPath.hasPrefix("/var/data/queue/") else {
            throw QueueError.invalidPath
        }
        let rawData = Data(bytes: messageBuffer.baseAddress!, count: writeOffset)
        let nonce = AES.GCM.Nonce()
        let sealed = try AES.GCM.seal(rawData, using: storageKey, nonce: nonce)
        guard let combined = sealed.combined else {
            throw QueueError.decryptionFailed
        }
        try combined.write(to: URL(fileURLWithPath: sanitizedPath))
    }

    // Function pointer table - read only dispatch, no arbitrary address injection
    func executeFromTable(index: Int, context: UnsafeRawPointer, size: Int) {
        guard index < handlers.count else { return }
        // Use the type-safe handlers array directly
        handlers[index](context, size)
    }

    deinit {
        messageBuffer.deallocate()
    }
}

enum QueueError: Error {
    case invalidHandler
    case bufferOverflow
    case decryptionFailed
    case invalidPath
}

// Default handlers
func logHandler(data: UnsafeRawPointer, length: Int) -> Void {
    let buffer = UnsafeBufferPointer(start: data.assumingMemoryBound(to: UInt8.self), count: length)
    print("LOG: received \(length) bytes")
}

func storeHandler(data: UnsafeRawPointer, length: Int) -> Void {
    print("STORE: persisting \(length) bytes")
}

func forwardHandler(data: UnsafeRawPointer, length: Int) -> Void {
    print("FORWARD: routing \(length) bytes")
}
